from jsonb_to_recordset($json$[{"id":"che-so-245","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A hypotonic solution, relative to a cell, has","options":["lower osmotic pressure","higher osmotic pressure","identical $\\pi$","zero solvent"],"answer_index":0,"explanation":"Water then enters the cell; the external solution is hypotonic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-246","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Reverse osmosis is used in","options":["desalination of sea water","measuring $K_b$ only","making azeotropes","recording NMR spectra"],"answer_index":0,"explanation":"Pressure greater than $\\pi$ drives solvent from the brine through a membrane, leaving salts behind.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-247","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"In $\\pi = CRT$, the symbol C stands for","options":["molarity of the solute","molality","mole fraction","mass percent"],"answer_index":0,"explanation":"Osmotic pressure uses the molar concentration (mol L⁻¹), not molality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-248","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Osmotic pressure is a","options":["colligative property","collisional nuclear property","surface colour","magnetic property"],"answer_index":0,"explanation":"For a given solvent it depends on the number of solute particles per unit volume.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-249","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A semipermeable membrane allows","options":["solvent molecules to pass but not the solute","both solute and solvent to pass freely","only ions to pass","only proteins to pass"],"answer_index":0,"explanation":"That selective permeability is what makes osmosis (and $\\pi$) observable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-250","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Plant cells placed in a hypertonic solution undergo","options":["plasmolysis","bursting","no change at all","photosynthesis only"],"answer_index":0,"explanation":"Water leaves the cell, the protoplast shrinks, and plasmolysis is observed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-251","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Berkeley and Hartley devised a laboratory method to measure","options":["osmotic pressure","$K_H$","mass percent","electron spin"],"answer_index":0,"explanation":"Their apparatus applies a measured pressure to just stop osmosis.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-252","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At constant temperature, osmotic pressure of a dilute non-electrolyte is proportional to","options":["the molar concentration","the square of the concentration","1/C","the solvent $K_b$"],"answer_index":0,"explanation":"$\\pi = CRT$ at fixed T is a direct proportion between $\\pi$ and C.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-253","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 M non-electrolyte at 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹) has $\\pi$ nearest","options":["2.46 atm","0.082 atm","3.00 atm","24.6 atm"],"answer_index":0,"explanation":"$\\pi = 0.10 \\times 0.0821 \\times 300 = 2.46$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-254","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Glucose 18 g (180 g mol⁻¹) in 1.0 L at 27 °C (R = 0.0821 L atm K⁻¹ mol⁻¹) shows $\\pi$ of","options":["2.46 atm","0.82 atm","18 atm","0.10 atm"],"answer_index":0,"explanation":"C = 0.10 mol L⁻¹, T = 300 K, so $\\pi = 0.10 \\times 0.0821 \\times 300 = 2.46$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-255","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Human blood is approximately isotonic with","options":["0.91% (w/v) NaCl","10% NaCl","pure water","5 M urea"],"answer_index":0,"explanation":"Physiological saline (~0.91% NaCl, about 0.16 M) matches the osmotic pressure of blood.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-256","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 2.0 g sample of a polymer in 1.0 L of solution at 300 K shows $\\pi = 4.1 \\times 10^{-4}$ atm (R = 0.082 L atm K⁻¹ mol⁻¹). Molar mass is nearest","options":["1.2 × 10⁵ g mol⁻¹","1.2 × 10³ g mol⁻¹","2.0 × 10⁴ g mol⁻¹","8.2 × 10² g mol⁻¹"],"answer_index":0,"explanation":"C = $\\pi / RT$ = 4.1 × 10⁻⁴ / (0.082 × 300) = 1.67 × 10⁻⁵ mol L⁻¹; M = 2.0 / 1.67 × 10⁻⁵ ≈ 1.2 × 10⁵.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
